import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 13
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    first = next(
        (i for i, row in enumerate(records)
         if len(row) > 1 or (row and row[0].strip())),
        len(records),
    )
    if first == len(records):
        return {"columns": [], "rows": []}

    def looks_like_header(row):
        labels = [value.strip() for value in row]
        return (
            len(labels) == expected_width
            and len(set(labels)) == expected_width
            and all(re.fullmatch(r"[^\W\d][\w\s./()%+\-]*", label)
                    for label in labels)
        )

    header_index = first
    # Only search past a leading preamble, not past a full-width record.
    for i in range(first, len(records)):
        if len(records[i]) == expected_width:
            if looks_like_header(records[i]):
                header_index = i
            break

    columns = list(records[header_index])
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        name = f"column_{position}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
